"""Internal subprocess entrypoint. Input paths are generated by the parent parser."""
import csv
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time

from pypdf import PdfReader
from backend.pdf_parser import MAX_PAGES, MAX_TEXT, ParseError


def extract(source, language):
    deadline = time.monotonic() + 105
    try:
        reader = PdfReader(source, strict=True)
        if reader.is_encrypted:
            raise ParseError('encrypted_pdf')
        if not 1 <= len(reader.pages) <= MAX_PAGES:
            raise ParseError('page_limit')
        pages, total = [], 0
        renderer = None
        for index, page in enumerate(reader.pages):
            if time.monotonic() >= deadline:
                raise ParseError('parse_timeout')
            text = page.extract_text() or ''
            method, quality = 'text', 'usable'
            if len(text.strip()) < 20:
                import pypdfium2 as pdfium
                if renderer is None:
                    renderer = pdfium.PdfDocument(str(source))
                render_page = renderer[index]
                width, height = render_page.get_size()
                if width <= 0 or height <= 0 or width * height * (300 / 72) ** 2 > 20_000_000:
                    raise ParseError('page_dimensions_limit')
                executable = os.environ.get('PRIVATE_TESSERACT') or shutil.which('tesseract')
                if not executable and Path('C:/Program Files/Tesseract-OCR/tesseract.exe').is_file():
                    executable = 'C:/Program Files/Tesseract-OCR/tesseract.exe'
                if not executable:
                    raise ParseError('ocr_unavailable')
                image_path = source.parent / f'page-{index}.png'
                render_page.render(scale=300/72).to_pil().save(image_path)
                command = [executable, str(image_path), 'stdout', '-l', language, '--psm', '6', '-c', 'tessedit_create_tsv=1']
                tessdata = os.environ.get('PRIVATE_TESSDATA')
                if tessdata:
                    command[3:3] = ['--tessdata-dir', tessdata]
                try:
                    result = subprocess.run(command, capture_output=True, timeout=max(.1,min(30,deadline-time.monotonic())),
                                            env={**os.environ, 'OMP_THREAD_LIMIT': '4'},
                                            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                except subprocess.TimeoutExpired:
                    raise ParseError('ocr_timeout') from None
                if result.returncode:
                    raise ParseError('ocr_language_or_runtime_unavailable')
                words = [r for r in csv.DictReader(io.StringIO(result.stdout.decode('utf-8')), delimiter='\t') if r['text'].strip()]
                text = ' '.join(r['text'] for r in words)
                confidence = sum(float(r['conf']) for r in words) / max(1, len(words))
                method = 'tesseract'
                quality = 'review' if confidence < 65 or len(text.strip()) < 20 else 'usable'
            total += len(text)
            if total > MAX_TEXT:
                raise ParseError('text_limit')
            pages.append({'number': index+1, 'text': text, 'method': method, 'quality': quality})
        return {'pages': pages}
    except ParseError as error:
        return {'error': error.code}
    except Exception:
        return {'error': 'invalid_pdf'}


if __name__ == '__main__':
    from backend.parser_limits import constrain_worker
    try:
        constrain_worker()
    except Exception:
        result = {'error': 'resource_isolation_unavailable'}
    else:
        result = extract(Path(sys.argv[1]), sys.argv[3])
    Path(sys.argv[2]).write_text(json.dumps(result), encoding='utf-8')
